import type {ReactElement, ReactNode} from 'react';
import type {
  NativeScrollEvent,
  NativeSyntheticEvent,
  StyleProp,
  ViewStyle,
} from 'react-native';

export interface ListItem {
  id: string | number;
  selected?: boolean;
}

export interface ListData<T extends ListItem = ListItem> {
  items: T[];
  pageIndex?: number;
  needLoadMore?: boolean;
}

export interface FetchDataParams<T extends ListItem = ListItem> {
  pageIndex: number;
  pageSize: number;
  prevItems: T[];
}

export interface RenderItemParams<T extends ListItem = ListItem> {
  item: T;
  index: number;
  selected?: boolean;
  onItemPress?: (item: T, index: number) => void;
}

export interface AdvancedFlatListProps<T extends ListItem = ListItem> {
  tag?: string;
  initialData?: Partial<ListData<T>>;
  initPageIndex?: number;
  pageSize?: number;
  fetchData: (params: FetchDataParams<T>) => Promise<ListData<T> | null>;
  renderItem?: (params: RenderItemParams<T>) => ReactNode;
  keyExtractor?: (item: T, index: number) => string;
  style?: StyleProp<ViewStyle>;
  contentContainerStyle?: StyleProp<ViewStyle>;
  ListHeaderComponent?: ReactNode;
  ListEmptyComponent?: React.ComponentType | ReactElement | null;
  autoRefresh?: boolean;
  disabledRefresh?: boolean;
  keyboardShouldPersistTaps?: 'always' | 'never' | 'handled';
  emptyText?: string;
  showListEmptyComponent?: boolean;
  onScrollBeginDrag?: (event: NativeSyntheticEvent<NativeScrollEvent>) => void;
  onScrollEndDrag?: (event: NativeSyntheticEvent<NativeScrollEvent>) => void;
  onEndReachedThreshold?: number;
  showsVerticalScrollIndicator?: boolean;
  extraData?: unknown;
  testID?: string;
  singleSelect?: boolean;
  onSingleSelectChange?: (selectedItem: T | null) => void;
  onItemPress?: (item: T, index: number) => void;
}

export interface AdvancedFlatListRef<T extends ListItem = ListItem> {
  scrollToTop: () => void;
  refresh: () => void;
  stopRefresh: () => void;
  getItems: () => T[];
  changeItemSelect: (index: number) => void;
  clearSelection: () => void;
}

export interface InternalState<T extends ListItem = ListItem> {
  items: T[];
  pageIndex: number;
  loading: boolean;
  refreshing: boolean;
  needLoadMore: boolean;
  selectedId: string | null;
}

export type FetchType = 'refresh' | 'loadMore';

import type {FetchType, ListData, ListItem} from './types';

export const getRequestedPageIndex = (
  type: FetchType,
  initPageIndex: number,
  currentPageIndex: number,
): number => (type === 'refresh' ? initPageIndex : currentPageIndex + 1);

export const mergeListItems = <T>(
  type: FetchType,
  previousItems: T[],
  nextItems: T[],
): T[] => (type === 'loadMore' ? [...previousItems, ...nextItems] : nextItems);

export const shouldLoadMore = ({
  itemCount,
  loading,
  refreshing,
  needLoadMore,
}: {
  itemCount: number;
  loading: boolean;
  refreshing: boolean;
  needLoadMore: boolean;
}): boolean => itemCount > 0 && !loading && !refreshing && needLoadMore;

export const applyFetchResult = <T extends ListItem>(
  type: FetchType,
  previousItems: T[],
  result: ListData<T> | null,
  requestedPageIndex: number,
): {
  items: T[];
  pageIndex: number;
  needLoadMore: boolean;
} => {
  if (!result) {
    return {
      items: type === 'refresh' ? [] : previousItems,
      pageIndex: type === 'refresh' ? requestedPageIndex : requestedPageIndex - 1,
      needLoadMore: false,
    };
  }

  return {
    items: mergeListItems(type, previousItems, result.items),
    pageIndex: requestedPageIndex,
    needLoadMore: Boolean(result.needLoadMore),
  };
};

