import React, {
  forwardRef,
  memo,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react';
import {
  ActivityIndicator,
  FlatList,
  ListRenderItem,
  RefreshControl,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';
import {applyFetchResult, getRequestedPageIndex, shouldLoadMore} from './list-state';
import {createStyles} from './styles';
import type {
  AdvancedFlatListProps,
  AdvancedFlatListRef,
  InternalState,
  ListItem,
  RenderItemParams,
} from './types';

const DefaultEmptyComponent = memo(function DefaultEmptyComponent({text}: {text: string}) {
  const styles = useMemo(() => createStyles(), []);
  return (
    <View style={styles.emptyContainer}>
      <Text style={styles.emptyText}>{text}</Text>
    </View>
  );
});

const DefaultListItem = memo(function DefaultListItem({
  item,
  index,
  onItemPress,
}: RenderItemParams) {
  const styles = useMemo(() => createStyles(), []);
  return (
    <TouchableOpacity
      onPress={() => onItemPress?.(item, index)}
      style={styles.defaultItem}
    >
      <Text>{JSON.stringify(item)}</Text>
    </TouchableOpacity>
  );
});

function AdvancedFlatListInner<T extends ListItem>(
  props: AdvancedFlatListProps<T>,
  ref: React.ForwardedRef<AdvancedFlatListRef<T>>,
) {
  const {
    tag = 'advanced',
    initPageIndex = 0,
    initialData = {},
    pageSize = 20,
    fetchData,
    renderItem,
    style,
    contentContainerStyle,
    ListHeaderComponent,
    ListEmptyComponent,
    autoRefresh = true,
    keyExtractor = (item: T) => String(item.id),
    disabledRefresh = false,
    emptyText = 'No data available',
    showListEmptyComponent = true,
    onScrollBeginDrag,
    onScrollEndDrag,
    onEndReachedThreshold = 0.5,
    keyboardShouldPersistTaps = 'never',
    showsVerticalScrollIndicator = false,
    extraData,
    testID,
    singleSelect = false,
    onSingleSelectChange,
    onItemPress,
  } = props;

  const [state, setState] = useState<InternalState<T>>({
    items: initialData.items ?? [],
    pageIndex: initialData.pageIndex ?? initPageIndex,
    loading: false,
    refreshing: false,
    needLoadMore: initialData.needLoadMore ?? false,
    selectedId: null,
  });

  const flatListRef = useRef<FlatList<T>>(null);
  const itemsRef = useRef<T[]>(state.items);
  const pageIndexRef = useRef(state.pageIndex);
  const selectedIdRef = useRef<string | null>(state.selectedId);
  const loadingRef = useRef(false);
  const refreshingRef = useRef(false);
  const fetchGenerationRef = useRef(0);
  const styles = useMemo(() => createStyles(), []);

  itemsRef.current = state.items;
  pageIndexRef.current = state.pageIndex;
  selectedIdRef.current = state.selectedId;

  const fetchDataInternal = useCallback(
    async (type: 'refresh' | 'loadMore') => {
      if (type === 'refresh') {
        if (refreshingRef.current) {
          return;
        }
        fetchGenerationRef.current += 1;
        refreshingRef.current = true;
        loadingRef.current = false;
      } else if (loadingRef.current || refreshingRef.current) {
        return;
      } else {
        loadingRef.current = true;
      }

      const generation = fetchGenerationRef.current;
      const requestedPageIndex = getRequestedPageIndex(
        type,
        initPageIndex,
        pageIndexRef.current,
      );

      setState(prev =>
        type === 'refresh'
          ? {...prev, refreshing: true, loading: false}
          : {...prev, loading: true, refreshing: false},
      );

      try {
        const result = await fetchData({
          pageIndex: requestedPageIndex,
          pageSize,
          prevItems: type === 'refresh' ? [] : itemsRef.current,
        });

        if (generation !== fetchGenerationRef.current) {
          return;
        }

        const next = applyFetchResult(type, itemsRef.current, result, requestedPageIndex);
        itemsRef.current = next.items;
        pageIndexRef.current = next.pageIndex;
        setState(prev => ({
          ...prev,
          items: next.items,
          pageIndex: next.pageIndex,
          needLoadMore: next.needLoadMore,
          loading: false,
          refreshing: false,
        }));
      } catch {
        if (generation !== fetchGenerationRef.current) {
          return;
        }
        const next = applyFetchResult(type, itemsRef.current, null, requestedPageIndex);
        itemsRef.current = next.items;
        pageIndexRef.current = next.pageIndex;
        setState(prev => ({
          ...prev,
          items: next.items,
          pageIndex: next.pageIndex,
          needLoadMore: next.needLoadMore,
          loading: false,
          refreshing: false,
        }));
      } finally {
        if (generation === fetchGenerationRef.current) {
          loadingRef.current = false;
          refreshingRef.current = false;
        }
      }
    },
    [fetchData, initPageIndex, pageSize],
  );

  const onRefresh = useCallback(() => {
    void fetchDataInternal('refresh');
  }, [fetchDataInternal]);

  useEffect(() => {
    if (autoRefresh) {
      void fetchDataInternal('refresh');
    }
    // Mount-only auto refresh keeps fetchDataInternal from retriggering on identity changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useImperativeHandle(
    ref,
    () => ({
      scrollToTop: () => {
        flatListRef.current?.scrollToOffset({animated: true, offset: 0});
      },
      refresh: onRefresh,
      stopRefresh: () => {
        refreshingRef.current = false;
        setState(prev => ({...prev, refreshing: false}));
      },
      getItems: () => itemsRef.current,
      changeItemSelect: (index: number) => {
        const currentItems = itemsRef.current;
        const target = currentItems[index];
        if (!target) {
          return;
        }
        if (singleSelect) {
          const itemId = keyExtractor(target, index);
          const nextSelectedId = selectedIdRef.current === itemId ? null : itemId;
          selectedIdRef.current = nextSelectedId;
          setState(prev => ({...prev, selectedId: nextSelectedId}));
          onSingleSelectChange?.(nextSelectedId === null ? null : target);
          return;
        }
        const nextItems = currentItems.map((item, idx) =>
          idx === index ? {...item, selected: !item.selected} : item,
        );
        itemsRef.current = nextItems;
        setState(prev => ({...prev, items: nextItems}));
      },
      clearSelection: () => {
        selectedIdRef.current = null;
        const nextItems = itemsRef.current.map(item =>
          item.selected ? {...item, selected: false} : item,
        );
        itemsRef.current = nextItems;
        setState(prev => ({...prev, selectedId: null, items: nextItems}));
        onSingleSelectChange?.(null);
      },
    }),
    [keyExtractor, onRefresh, onSingleSelectChange, singleSelect],
  );

  const loadMoreItems = useCallback(() => {
    if (
      !shouldLoadMore({
        itemCount: itemsRef.current.length,
        loading: loadingRef.current,
        refreshing: refreshingRef.current,
        needLoadMore: state.needLoadMore,
      })
    ) {
      return;
    }
    void fetchDataInternal('loadMore');
  }, [fetchDataInternal, state.needLoadMore]);

  const handleItemPress = useCallback(
    (item: T, index: number) => {
      onItemPress?.(item, index);
      if (!singleSelect) {
        return;
      }
      const itemId = keyExtractor(item, index);
      const nextSelectedId = selectedIdRef.current === itemId ? null : itemId;
      selectedIdRef.current = nextSelectedId;
      setState(prev => ({...prev, selectedId: nextSelectedId}));
      onSingleSelectChange?.(nextSelectedId === null ? null : item);
    },
    [keyExtractor, onItemPress, onSingleSelectChange, singleSelect],
  );

  const renderFooter = useCallback(() => {
    if (!state.loading) {
      return null;
    }
    return (
      <View style={styles.loader}>
        <ActivityIndicator size="small" />
      </View>
    );
  }, [state.loading, styles.loader]);

  const renderItemWrapper: ListRenderItem<T> = useCallback(
    ({item, index}) => {
      const selected = singleSelect
        ? state.selectedId === keyExtractor(item, index)
        : Boolean(item.selected);

      if (renderItem) {
        return renderItem({item, index, selected, onItemPress: handleItemPress}) as React.ReactElement | null;
      }

      return (
        <DefaultListItem
          item={item}
          index={index}
          selected={selected}
          onItemPress={handleItemPress as RenderItemParams['onItemPress']}
        />
      );
    },
    [handleItemPress, keyExtractor, renderItem, singleSelect, state.selectedId],
  );

  const renderEmptyComponent = useCallback(() => {
    if (!showListEmptyComponent || refreshingRef.current || state.refreshing) {
      return null;
    }
    return ListEmptyComponent ?? <DefaultEmptyComponent text={emptyText} />;
  }, [ListEmptyComponent, emptyText, showListEmptyComponent, state.refreshing]);

  return (
    <FlatList<T>
      key={tag}
      testID={testID}
      ref={flatListRef}
      style={[styles.flatList, style]}
      contentContainerStyle={[styles.contentContainer, contentContainerStyle]}
      ListHeaderComponent={ListHeaderComponent}
      data={state.items}
      extraData={extraData ?? state.selectedId}
      renderItem={renderItemWrapper}
      keyExtractor={keyExtractor}
      refreshControl={
        !disabledRefresh ? (
          <RefreshControl refreshing={state.refreshing} onRefresh={onRefresh} />
        ) : undefined
      }
      onScrollBeginDrag={onScrollBeginDrag}
      onScrollEndDrag={onScrollEndDrag}
      onEndReached={loadMoreItems}
      onEndReachedThreshold={onEndReachedThreshold}
      ListFooterComponent={renderFooter}
      showsVerticalScrollIndicator={showsVerticalScrollIndicator}
      ListEmptyComponent={renderEmptyComponent}
      keyboardShouldPersistTaps={keyboardShouldPersistTaps}
    />
  );
}

const AdvancedFlatList = memo(forwardRef(AdvancedFlatListInner)) as <T extends ListItem>(
  props: AdvancedFlatListProps<T> & {ref?: React.Ref<AdvancedFlatListRef<T>>},
) => React.ReactElement | null;

export default AdvancedFlatList;

