  applyFetchResult,
  getRequestedPageIndex,
  mergeListItems,
  shouldLoadMore,
} from './list-state';

import {
  applyFetchResult,
  getRequestedPageIndex,
  mergeListItems,
  shouldLoadMore,
} from '../src/list-state';
import type {ListItem} from '../src/types';

interface Item extends ListItem {
  title: string;
}

const item = (id: number): Item => ({id, title: `Item ${id}`});

describe('getRequestedPageIndex', () => {
  it('returns the initial page on refresh', () => {
    expect(getRequestedPageIndex('refresh', 0, 4)).toBe(0);
  });

  it('increments the current page on load more', () => {
    expect(getRequestedPageIndex('loadMore', 0, 2)).toBe(3);
  });
});

describe('mergeListItems', () => {
  it('replaces items on refresh', () => {
    expect(mergeListItems('refresh', [item(1)], [item(2)])).toEqual([item(2)]);
  });

  it('appends items on load more', () => {
    expect(mergeListItems('loadMore', [item(1)], [item(2)])).toEqual([item(1), item(2)]);
  });
});

describe('shouldLoadMore', () => {
  it('allows load more only when the list has data and more pages', () => {
    expect(
      shouldLoadMore({
        itemCount: 20,
        loading: false,
        refreshing: false,
        needLoadMore: true,
      }),
    ).toBe(true);
  });

  it('does not load more for an empty list or while a request is in flight', () => {
    expect(
      shouldLoadMore({
        itemCount: 0,
        loading: false,
        refreshing: false,
        needLoadMore: true,
      }),
    ).toBe(false);
    expect(
      shouldLoadMore({
        itemCount: 20,
        loading: true,
        refreshing: false,
        needLoadMore: true,
      }),
    ).toBe(false);
    expect(
      shouldLoadMore({
        itemCount: 20,
        loading: false,
        refreshing: true,
        needLoadMore: true,
      }),
    ).toBe(false);
    expect(
      shouldLoadMore({
        itemCount: 20,
        loading: false,
        refreshing: false,
        needLoadMore: false,
      }),
    ).toBe(false);
  });
});

describe('applyFetchResult', () => {
  it('replaces items and keeps the requested page after a successful refresh', () => {
    expect(
      applyFetchResult(
        'refresh',
        [item(1)],
        {items: [item(10), item(11)], needLoadMore: true},
        0,
      ),
    ).toEqual({
      items: [item(10), item(11)],
      pageIndex: 0,
      needLoadMore: true,
    });
  });

  it('appends items after a successful load more', () => {
    expect(
      applyFetchResult(
        'loadMore',
        [item(1)],
        {items: [item(2)], needLoadMore: false},
        1,
      ),
    ).toEqual({
      items: [item(1), item(2)],
      pageIndex: 1,
      needLoadMore: false,
    });
  });

  it('does not skip a page when load more fails', () => {
    expect(applyFetchResult('loadMore', [item(1)], null, 1)).toEqual({
      items: [item(1)],
      pageIndex: 0,
      needLoadMore: false,
    });
  });

  it('clears items when refresh returns null', () => {
    expect(applyFetchResult('refresh', [item(1)], null, 0)).toEqual({
      items: [],
      pageIndex: 0,
      needLoadMore: false,
    });
  });
});

